-- Liga conquistas já cadastradas ao projeto correspondente (só onde ainda não há ligação).
begin;
update public.conquistas set projeto_id=(select id from public.projetos where slug='kit-de-robotica-educacional-sem-o-uso-de-telas') where projeto_id is null and (tipo='TCC' and titulo ilike 'Desenvolvimento de um kit de robótica educacional sem o uso de telas') and exists (select 1 from public.projetos where slug='kit-de-robotica-educacional-sem-o-uso-de-telas');
update public.conquistas set projeto_id=(select id from public.projetos where slug='veiculo-aereo-nao-tripulado-do-tipo-quadrotor') where projeto_id is null and (tipo='TCC' and titulo ilike '%veículo aéreo não tripulado do tipo quadrotor') and exists (select 1 from public.projetos where slug='veiculo-aereo-nao-tripulado-do-tipo-quadrotor');
update public.conquistas set projeto_id=(select id from public.projetos where slug='submarino') where projeto_id is null and (titulo ilike '%submarino robótico open-source%' or titulo ilike 'Construção de um submarino robô%' or titulo ilike 'Simulador de um Submarino') and exists (select 1 from public.projetos where slug='submarino');
update public.conquistas set projeto_id=(select id from public.projetos where slug='rov') where projeto_id is null and (titulo ilike 'Desenvolvimento de um veículo subaquático%' or titulo ilike 'A Low-Cost Remotely Operated Underwater Vehicle%' or titulo ilike 'Low-Cost ROV:%') and exists (select 1 from public.projetos where slug='rov');
update public.conquistas set projeto_id=(select id from public.projetos where slug='vlc') where projeto_id is null and (titulo ilike '%comunicação aplicada à robótica subaquática%' or titulo ilike 'Low-Cost Optical Communication System%') and exists (select 1 from public.projetos where slug='vlc');
update public.conquistas set projeto_id=(select id from public.projetos where slug='peixe-robo') where projeto_id is null and (titulo ilike '%peixe robótico utilizando tecnologia de impressão 3D' or titulo ilike 'A Low-Cost and Open-Source Robotic Fish%') and exists (select 1 from public.projetos where slug='peixe-robo');
update public.conquistas set projeto_id=(select id from public.projetos where slug='drone-autonomo-para-aplicacoes-logisticas') where projeto_id is null and (tipo='TCC' and titulo ilike '%drone autônomo para aplicações industriais e logísticas') and exists (select 1 from public.projetos where slug='drone-autonomo-para-aplicacoes-logisticas');
update public.conquistas set projeto_id=(select id from public.projetos where slug='detector-de-fome-em-peixes') where projeto_id is null and (titulo ilike 'AquaFeed:%') and exists (select 1 from public.projetos where slug='detector-de-fome-em-peixes');
update public.conquistas set projeto_id=(select id from public.projetos where slug='dispositivo-de-sensores-ambientais') where projeto_id is null and (titulo ilike '%Plataforma Multissensor para Monitoramento Ambiental Urbano') and exists (select 1 from public.projetos where slug='dispositivo-de-sensores-ambientais');
update public.conquistas set projeto_id=(select id from public.projetos where slug='simulador-em-realidade-aumentada-para-ensino-de-programacao-e-robotica') where projeto_id is null and (titulo ilike 'Simulador em realidade aumentada para ensino de programação e robótica') and exists (select 1 from public.projetos where slug='simulador-em-realidade-aumentada-para-ensino-de-programacao-e-robotica');
update public.conquistas set projeto_id=(select id from public.projetos where slug='ambiente-virtual-de-aprendizagem-com-inteligencia-artificial') where projeto_id is null and (titulo ilike 'Desenvolvimento de um ambiente virtual de aprendizagem%') and exists (select 1 from public.projetos where slug='ambiente-virtual-de-aprendizagem-com-inteligencia-artificial');
update public.conquistas set projeto_id=(select id from public.projetos where slug='realidade-virtual-e-aumentada-na-sala-de-aula') where projeto_id is null and (titulo ilike 'Realidade virtual e aumentada: apoio para a prática%') and exists (select 1 from public.projetos where slug='realidade-virtual-e-aumentada-na-sala-de-aula');
update public.conquistas set projeto_id=(select id from public.projetos where slug='robotica-para-ensinar-matematica-em-ongs') where projeto_id is null and (titulo ilike 'Robótica como ferramenta criativa para o ensino%') and exists (select 1 from public.projetos where slug='robotica-para-ensinar-matematica-em-ongs');
update public.conquistas set projeto_id=(select id from public.projetos where slug='fusao-de-dados-sensoriais-para-navegacao-de-robos-moveis') where projeto_id is null and (titulo ilike 'Fusão de dados sensoriais para navegação%') and exists (select 1 from public.projetos where slug='fusao-de-dados-sensoriais-para-navegacao-de-robos-moveis');
update public.conquistas set projeto_id=(select id from public.projetos where slug='modelo-de-negocios-de-um-fablab-para-o-ifs-campus-lagarto') where projeto_id is null and (titulo ilike 'Desenvolver e implementar o modelo de negócios de um Fab Lab%') and exists (select 1 from public.projetos where slug='modelo-de-negocios-de-um-fablab-para-o-ifs-campus-lagarto');
update public.conquistas set projeto_id=(select id from public.projetos where slug='robo-autonomo-de-baixo-custo-para-futebol-de-robos') where projeto_id is null and (titulo ilike 'Produção de um robô de baixo custo para o time de futebol de robôs') and exists (select 1 from public.projetos where slug='robo-autonomo-de-baixo-custo-para-futebol-de-robos');
update public.conquistas set projeto_id=(select id from public.projetos where slug='software-de-controle-de-prestacao-de-contas') where projeto_id is null and (titulo ilike 'Prestação de Contas Simplificada%') and exists (select 1 from public.projetos where slug='software-de-controle-de-prestacao-de-contas');
update public.conquistas set projeto_id=(select id from public.projetos where slug='estimacao-de-pose') where projeto_id is null and (titulo ilike 'Sistema de Detecção de Gestos Para Controle de Drone%') and exists (select 1 from public.projetos where slug='estimacao-de-pose');
commit;
select p.titulo as projeto, count(*) as conquistas from public.conquistas c join public.projetos p on p.id=c.projeto_id group by 1 order by 2 desc, 1;
